import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'parent': '10738', 'gloss': ['eggplant'], 'forms': ['ringaṇā', 'rīŋaṇa', 'rīngaṇā', 'riŋaṇo', 'riŋaṇā', 'rīŋṇa', 'ringaṇe', 'rīngaṇū', 'rīŋaṇā', 'riŋəṇā', 'eriŋgaṇɔ', 'riŋgaṇe', 'riŋaṇa'], 'citation': 'CDIAL[10738]', 'evidence': 'Turner explicitly gives Gujarati/Marathi rĩgṇī eggplant (Solanum jacquinii), Gujarati rĩgṇũ fruit and Marathi rĩgṇẽ under riṅgaṇī. These Bhili/Nimadi survey r(i)ŋ(g)aṇ- forms fit that western plant-name family, including weakened or unrecorded g; the generic survey eggplant sense does not identify the exact botanical species or prove Turner’s tentative deeper connection with riṅg creep.'}, {'parent': '11503', 'gloss': ['eggplant'], 'forms': ['bãīgɔ̃ṇ', 'bæŋan', 'bayŋgaṇā', 'beɣan'], 'citation': 'CDIAL[11503,1]', 'evidence': 'Turner’s first vātiṅgaṇa branch explicitly includes Oriya bāiṅgaṇa, Punjabi baĩgaṇ/vaĩgaṇ and Hindi baigan/baĩgun. These intact Oriya/Gujari/Haryanvi/Pothwari responses fit that inherited regional family. The retained-t northwestern forms, explicitly traced through Iranian in Turner, and responses containing a second crop name are excluded.'}, {'parent': '9369', 'gloss': ['eggplant'], 'forms': ['bʰenṭā', 'bʰʸānṭā', 'bhāṭṭe'], 'languages': ['Majhi', 'Nimadi'], 'citation': 'CDIAL[9369,1]', 'evidence': 'Turner gives Bihari bhaṇṭā and Maithili/Awadhi bhā̃ṭā eggplant under bhaṇṭākī. Majhi bh(y)enṭā/bhyānṭā and Nimadi bhāṭṭe match that bh–ṭ plant-name family with regional vowel and stop-cluster outcomes. The i-vowel bhiṇṭikā subgroup with Nepali bhĩṛā/bhẽṛā is not selected.'}, {'parent': '6835', 'gloss': ['dust'], 'forms': ['dʰul', 'dhuḍau', 'duṛin'], 'citation': 'CDIAL[6835 and addenda]', 'evidence': 'Turner explicitly includes Hindi dhūl and Western Pahari/Jaunsari dhūṛ dust, with Kotgarhi dhvḷo. These Haryanvi, Jaunsari and Kullui forms preserve the dust stem with ordinary regional vowels/endings; this excludes longer dhūdhar and rajas-like responses whose extra morphology needs separate evidence.'}, {'parent': '6835', 'gloss': ['dust'], 'forms': ['duṛli', 'dʰuṛli', 'ḍuṛla', 'dūrlī', 'dʰūrlī'], 'languages': ['Bhatri', 'AdivasiOriya'], 'citation': 'CDIAL[6835]', 'evidence': 'Turner gives both Oriya dhuḷi and dialectal dhūri dust within the same dhūḍi/dhūli family. The neighbouring Bhatri/Adivasi Oriya duṛli/dūrli forms contain both liquids and are placed in that family as a qualified regional comparison, not as evidence for an asserted regular insertion rule. The source’s aspiration and liquid spellings are unchanged.'}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
for r in rs:
 if r['ID'] not in done and r['Gloss']=='eggplant' and ('mū' in r['Form'] or 'mūŋ' in r['Form'] or 'būm' in r['Form'] or 'maŋ' in r['Form'] or 'palī' in r['Form']):
  h.append(dict(record=r,reason='The response combines an eggplant-like form with a mung/groundnut-like second answer, or contains a ditto/gap marker. Likely adjacent-answer overlap must be checked against the printed survey layout before etymologising the whole record. No source reparse or spelling change is performed in this no-rebuild review.'))
(P/'pass044-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass044-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
